package hotel.reservations;

import java.util.List;
import java.util.Optional;
import java.util.function.Supplier;

/** The one place that turns the identification fields (as sent by the site or saved in the database) into a kind. */
public final class Identifications {

    private Identifications() {
    }

    /** Exactly one kind must be fully filled in and no field of another kind may be present. */
    public static Identification of(String cpf, String companyCnpj, String companyName, String passport,
            String country) {
        List<Optional<Identification>> kinds = List.of(
                kind(() -> new CpfIdentification(cpf), cpf),
                kind(() -> new CompanyIdentification(companyCnpj, companyName), companyCnpj, companyName),
